import threading
from contextlib import contextmanager

_lock = threading.Lock()


@contextmanager
def exclusive():
    _lock.acquire()
    try:
        yield
    finally:
        _lock.release()


@contextmanager
def transaction(conn):
    try:
        yield conn
    except Exception:
        conn.rollback()
        raise
    conn.commit()

